data.policy:
path "pki-internal/issuers" { capabilities = ["list"] }
path "pki-internal/issuer/+" { capabilities = ["read"] }
path "pki-internal/roles" { capabilities = ["list"] }
path "pki-internal/roles/+" { capabilities = ["read"] }
path "pki-internal/certs" { capabilities = ["list"] }
path "pki-internal/cert/+" { capabilities = ["read"] }
path "pki-internal/config/urls" { capabilities = ["read"] }
path "pki-internal/config/issuers" { capabilities = ["read"] }
path "pki-internal/config/cluster" { capabilities = ["read"] }
path "pki-internal/config/crl" { capabilities = ["read"] }
path "pki-internal/config/auto-tidy" { capabilities = ["read"] }
# optional: who may request from each role
path "sys/policies/acl" { capabilities = ["list"] }
path "sys/policies/acl/+" { capabilities = ["read"] }
